package com.sas;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import static org.junit.jupiter.api.Assertions.*;

import com.sas.util.PasswordUtil;

/**
 * Regression tests for PasswordUtil BCrypt verification.
 *
 * <p>The seed.sql file uses BCrypt revision $2b$ (generated by Python's
 * bcrypt library). The jbcrypt Java library only accepts $2a$.
 * PasswordUtil.verify() normalises the revision prefix so both work.</p>
 */
@DisplayName("PasswordUtil — BCrypt $2b$ compatibility")
class PasswordUtilTest {

    @Test
    @DisplayName("admin123 verifies against the $2b$ seed hash")
    void testAdminSeedHash() {
        String seedHash = "$2b$12$Uij5QAo8tKFt303clrsQU..2ArrxX1mTQGmC.9TJfNm43jfKjMR3i";
        assertTrue(PasswordUtil.verify("admin123", seedHash),
            "admin123 must verify against the $2b$ seed hash");
    }

    @Test
    @DisplayName("student123 verifies against the $2b$ seed hash")
    void testStudentSeedHash() {
        String seedHash = "$2b$12$SUhuBCtqgCiMJB672K59cus6fcc953BTpAcEN0rjKEcNFDlYfiDRy";
        assertTrue(PasswordUtil.verify("student123", seedHash),
            "student123 must verify against the $2b$ seed hash");
    }

    @Test
    @DisplayName("wrong password does NOT verify against $2b$ seed hash")
    void testWrongPasswordFails() {
        String seedHash = "$2b$12$Uij5QAo8tKFt303clrsQU..2ArrxX1mTQGmC.9TJfNm43jfKjMR3i";
        assertFalse(PasswordUtil.verify("wrongpassword", seedHash),
            "wrong password must NOT verify");
    }

    @Test
    @DisplayName("a freshly hashed $2a$ password also verifies (no regression)")
    void testNativeHash() {
        String hash = PasswordUtil.hash("testpass");
        assertTrue(PasswordUtil.verify("testpass", hash),
            "a freshly hashed password must verify");
        assertFalse(PasswordUtil.verify("otherpass", hash),
            "a different password must NOT verify");
    }

    @Test
    @DisplayName("null and empty inputs return false, not throw")
    void testNullSafety() {
        assertFalse(PasswordUtil.verify(null, "$2a$12$abc"));
        assertFalse(PasswordUtil.verify("abc", null));
        assertFalse(PasswordUtil.verify("abc", ""));
    }
}
